INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12166, 'Khuuteekha', 'lumasaaba', 'Ise indi khuuyeetakho mu khuun’goonan’goona tsinyanyi tse khuuliila biilyo. Ne iliwo ndweela khu nyanyi tseesi ikhakana khuukholakho ta. Nível: First words. Ilustração: Kathy Arbuckle.', 'http://africanstorybook.org/illustrations/covers/8745.png', NULL, 438, 25, 20, 'asp-8745', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12167, 'Okufumba', 'lusoga', 'Ndi kuyamba kutegeka iva lya kulya. Ndi ne eiva ilala liti lyentayenda kutegeka. Nível: First words. Ilustração: Kathy Arbuckle.', 'http://africanstorybook.org/illustrations/covers/8746.png', NULL, 1037, 25, 20, 'asp-8746', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12168, 'Ukubala', 'zu', 'Bala izilwane eziyophuza. Kwenzekani uma ibhubesi lifika ukuzophuza? Nível: First words. Ilustração: Gay Galsworthy.', 'http://africanstorybook.org/illustrations/covers/8748.png', NULL, 162, 25, 20, 'asp-8748', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12169, 'Dede Vile A’Bua Ri', 'lugbarati-(official)', 'Zámvá gǎkányaá rʉ́ rɨ̀bà àvá àlʉɨ́mà ìdî nɨ nèzʉ àbʉ́á otʉ̂rɨábàzʉ́ nɨzʉ́. Nènɨ́ pàrí dèdé nɨ́ àbʉ́ábazʉ́ nɨzʉ́ rɨ̀ kʉ. Èrɨ nga sâdu ngòpɨ́ ká zámvá ndê rɨ nɨ̀ nga pàríɨ́mà dèdè nɨ àbʉ́ábàzʉ rɨ̀ nɨ ndò? Nível: Longer paragraphs. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/8749.png', NULL, 1473, 25, 20, 'asp-8749', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12170, 'Patí Éfɨ́', 'lugbarati-(official)', 'Zámvá àzɨ́ ndrìzàrʉ́ nɨ ndrâ cɨ́bá drɨ́á nɨ́ lě jé òkʉ́ rʉ nɨ. Yɨ vɨ́lé  àkú drìá Nível: Read aloud. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8750.png', NULL, 1473, 25, 20, 'asp-8750', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12171, 'Ágúpí Òkò Rɨ̀ Pɨ Òkʉ́ Òkò Rɨ̀ Be', 'lugbarati-(official)', 'Ódʉ́kódɨ̀ nze eyó nyákú mà e’dózà pɨ mà drìábá áda alénɨá òkòdɨ̀yɨ be.Bádɨ̀yɨ èfʉ̌ drɨ́á engázʉ́ yí àlíó álírʉ́ bɨ̀zàrʉ́ àzɨ́nɨ ambɨ́zàrʉ́ rɨ̀ mà ètɨ́ádálá kɨ̀lé órí lé ecázʉ́ wúdrìkúrù ètú mà drɨzà be àzɨ́nɨ wúrá be ndrɨ̀zàrʉ́ rɨ̀ mà drɨ̀á. Yɨ nɨ́ èfʉ̀zʉ́ nyákú drìá rɨ̀á Nível: First paragraphs. Ilustração: Jemma Kahn.', 'http://africanstorybook.org/illustrations/covers/8751.png', NULL, 4340, 25, 20, 'asp-8751', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12172, 'Àfaamázʉ́', 'lugbarati-(official)', 'E’yóegázʉ́ àmae’yóamáaàmaruáàfandʉ́ndʉ́ yisɨ̀ àzɨ́nɨ  ‘bándʉ́ndʉ́ yisɨ̀ ngónɨyàrɨ̀ màdrìá. Nível: First words. Ilustração: Kathy Arbuckle.', 'http://africanstorybook.org/illustrations/covers/8752.png', NULL, 471, 25, 20, 'asp-8752', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12173, 'Kàlàfé Làzà', 'lugbarati-(official)', 'Àma ànyàpá áséá ‘dɨ̀yɨ mà kàlàfe làa yɨní mùría yí mvuriá. Mí egá àdɨ e’yó ecó ɨ̀ ‘yé nɨ̀ kàmì kà emú yí mvuriá nɨ̀ rɨ̀á? Nível: First words. Ilustração: Gay Galsworthy.', 'http://africanstorybook.org/illustrations/covers/8753.png', NULL, 1080, 25, 20, 'asp-8753', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12174, 'Nyaká A’Dɨ́zà', 'lugbarati-(official)', 'Ma mâ andrî mà  àzà ko nyaká a’dízà sɨ̀. Tíbí ini àźɨ àlʉ má lè nɨ èri mà  adɨ́zà   kʉ. Nível: First words. Ilustração: Kathy Arbuckle.', 'http://africanstorybook.org/illustrations/covers/8754.png', NULL, 674, 25, 20, 'asp-8754', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12175, 'Anzɨ Òdirì Rʉ́ Dɨ̀yɨ', 'lugbarati-(official)', 'Àkʉ́ àzɨ́ ndrâ àlʉ anzɨ ìnzìtáá rʉ́ nɨ  yɨ be. E’yó ònzɨ́rɨ̀ ‘bá édé ndrá yɨ òdirì sɨ̀. E’yó nɨ sɨ̀; yɨ ndrâ  àzɨ́ nga  íní nɨ́ yɨ kàzʉ́ akázʉ́ ànɨ́  kʉrɨ̀sɨ̀. Te mvá  àlʉ rɨ̀ nɨ́ lèlé àngʉ̀ nyakʉ́drìá rɨ̀ nɨ edâ  ètúsɨ̀ ngónɨá  rɨ̀ ndrě rá rɨ̀ sɨ̀ èfʉ̀ àmvé. Nga  dɨ́ aká ra. Càndɨ́ fʉ èrɨ mà adrípí yɨ tʉ̀. É’dó gèrì ndǎ èrɨ mà àzàkozʉ́. Nível: First sentences. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8755.png', NULL, 1147, 25, 20, 'asp-8755', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12176, 'Bàdàrʉ́ Pi Bʉ́nɨ̀ Be', 'lugbarati-(official)', 'Bàdàrú lè avɨ́tá sǎrʉ́ Nível: First words. Ilustração: Sorit Gupto.', 'http://africanstorybook.org/illustrations/covers/8756.png', NULL, 4341, 25, 20, 'asp-8756', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12177, 'Òkàlàkʉ̀kàlà', 'lugbarati-(official)', 'Bkʉ̀ ‘dɨ̀rɨ  alia e’yo  ‘dɨyɨ pɨ  e’dá pie  e’yó nze àfa drɨa àma àgeɨa o’dʉ́ drɨ́asɨ  wʉ́rá be òkàlàkʉ̀kàlà rʉ dɨ̀yɨ mà drǐa. Nível: First words. Ilustração: Sue Kramer.', 'http://africanstorybook.org/illustrations/covers/8757.png', NULL, 1080, 25, 20, 'asp-8757', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12178, 'Má Vɨ́lé Búsùá Ngʉ̀á Yǎ?', 'lugbarati-(official)', 'Má vɨ́lé búsùá  àvɨ̀ rá. Mɨ́ ecó mánɨ́ má vɨ́lé búsùá ně pàrɨ àzɨ́á rá rô? Nível: First words. Ilustração: Bronwen Heath.', 'http://africanstorybook.org/illustrations/covers/8760.png', NULL, 1473, 25, 20, 'asp-8760', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12179, 'Má Vɨ́lé Pati Pòyé Avɨ́zʉ́ Rɨ̀ Ngòá Yǎ?', 'lugbarati-(official)', 'Ágúpíámvá àzɨ́nɨ nɨɨ́ vɨ́lé pàtí pòyé avɨ́zʉ́ rɨ̀ ndà. Èrɨ nga esú rá yǎ? Nível: First sentences. Ilustração: Rijuta Ghate.', 'http://africanstorybook.org/illustrations/covers/8761.png', NULL, 4341, 25, 20, 'asp-8761', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12180, 'Búkù Àngù Mile Nɨ́ Rɨ̀', 'lugbarati-(official)', 'E’yó ònìzʉ́ àngʉ̀ mile mà ojatáá ndʉ́ ndʉ́ ‘dɨ̀yɨ mà drìá àzɨ́nɨ ojatáá ndê yi fèe ‘bá yi yi mà ruá amáa ngónɨ yàrɨ̀ be. Nível: First words. Ilustração: Sandra McDougall.', 'http://africanstorybook.org/illustrations/covers/8762.png', NULL, 471, 25, 20, 'asp-8762', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12181, '‘Dì Má Ɨ́', 'lugbarati-(official)', 'Mí là e’yó má mà drì á: Ma à’dí ‘ɨ́ yàrì Nível: First words. Ilustração: Kathy Arbuckle.', 'http://africanstorybook.org/illustrations/covers/8763.png', NULL, 674, 25, 20, 'asp-8763', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12182, 'Òkpóróá E''yó Nzépɨ  Ɨ̀ndɨ̀ Rɨ̀', 'lugbarati-(official)', 'Ezóanzɨ nyɨrɨ nyɨrɨ na fúdrì ágú àzɨ́nɨ ézʉ́ Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8764.png', NULL, 4342, 25, 20, 'asp-8764', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12183, 'Kaíkó Engápɨ Engárɨ̀', 'lugbarati-(official)', 'Ɨ́sa kaíkó éfɨ́ rá mɨ́ nè dɨ́ à’dɨ nɨ nga ɨ ‘ye nɨ̀ yà rɨ̀ ɨ́kà yí òdàa drìniá àzɨ́nɨ àgeyí nɨ tè rɨ̀á. Nível: First words. Ilustração: Mlungisi Dlamini.', 'http://africanstorybook.org/illustrations/covers/8766.png', NULL, 471, 25, 20, 'asp-8766', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12184, 'Aria Ozoo Edepi Ri', 'lugbarati-(official)', 'Àrɨ́á àzɨ́nɨ  ndrâ ndrɨ̀zà rʉ́ cɨ́ jèrè mà alɨ́á ágádǔádálé Nível: Read aloud. Ilustração: Wiehan de Jager and Nalibali.', 'http://africanstorybook.org/illustrations/covers/8767.png', NULL, 1473, 25, 20, 'asp-8767', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12185, 'Àràkílíkò', 'lugbarati-(official)', 'Ágúpímvá òděa rʉ nɨ esú azɨnɨ gbɨ àràkílíkò. Ji àríá ndě mà àvù fé mbàzàʉ àzɨ  yɨ vílé ényátiá nɨ drí. Mbàzàʉ ‘dà a’dí azɨnɨ nya àràkílíkò ‘dà rá. Nível: First sentences. Ilustração: Joshua Waswa.', 'http://africanstorybook.org/illustrations/covers/8768.png', NULL, 674, 25, 20, 'asp-8768', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12186, 'Àbàzà Ágú Óká Dípɨ Rɨ̀ Nɨ́ Esúlérɨ̀', 'lugbarati-(official)', 'Ópɨ́ àzɨ́nɨ omve ándráa ágú óká dípɨ nɨɨ́ vɨ́lé àkúá. Ópɨ́dà lè ágú óká dípɨda mà siínɨ́bá áda àzɨ́  ecopɨ owʉ́pɨ míndre sɨ̀ àzɨ́nɨ èrɨ mà àrɨ́ nɨ́ rǎzbá áda vɨ́lé rɨ̀ lé rá nɨ aya sɨ̀ . eyó ópɨ́ nɨ́yódɨ̀ fè òrì ágú óká dǐpɨdɨ̀ mà ásíá káyɨ̀. Nìráɨ́ ecónɨ́ gǎ ópɨ́ nɨ́ kʉ Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8769.png', NULL, 471, 25, 20, 'asp-8769', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12187, 'Sí', 'lugbarati-(official)', 'Ànyàpá ndʉ́ ndʉ́ yɨ mà sɨ́ có èselé rá (àzɨ́dɨ̀yi mà sí vɨ́nɨ yo). Àma nɨ́ zòrɨá àdɨ àfa nɨɨ́ye àmà sí be nɨ̀ yà? Nível: First words. Ilustração: Kathy Arbuckle.', 'http://africanstorybook.org/illustrations/covers/8770.png', NULL, 844, 25, 20, 'asp-8770', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12188, 'O''dú Ázɨ́á Má Òndré Àngù Nɨ́ Drɨzʉ́ Tù Rɨ̀', 'lugbarati-(official)', 'Odú àlʉ Nível: First paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8771.png', NULL, 1473, 25, 20, 'asp-8771', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12189, 'Nyaká Ò’Bíti Sɨ̀rɨ̀', 'lugbarati-(official)', 'Mɨ má ésʉ áfá ámánɨ lèlé nyá lé o`bɨtí sì mâ átî be `díyí. Nível: First words. Ilustração: Cathy Feek.', 'http://africanstorybook.org/illustrations/covers/8773.png', NULL, 4342, 25, 20, 'asp-8773', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12190, 'Èbìóejí `báyinɨ́ Á`dɨ́kóyiawaá', 'lugbarati-(official)', 'Ndrâdrìòrɨ̀ sɨ̀ Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8774.png', NULL, 1080, 25, 20, 'asp-8774', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12191, 'Èbìó Pɨ Òndʉ̀á Be', 'lugbarati-(official)', 'Mungu wa angani anaamua kumpa Buibui Anansi chungu cha hekima. Anasisimka sana kutoka na yale anajifunza kiasi cha kutaka kukificha chungu hicho mtini ili afaidike pekee yake.  Kwa bahati mbaya Nível: Read aloud. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8775.png', NULL, 1473, 25, 20, 'asp-8775', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12192, 'Ìbíó Pi Ròkó Be', 'lugbarati-(official)', 'Ìbìó nɨ àlɨ́órʉ te èrɨ mà ágyíi ètóó nɨ ndrá lonyɨ be nɨ̀. Ìbìó nɨ aá àyà be rɨ̀ sɨ̌ Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8776.png', NULL, 1080, 25, 20, 'asp-8776', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12193, 'Ànɨ́kánɨ̀kà Pɨ Òkùkù Be', 'lugbarati-(official)', 'Ànìkáníka lènɨ́ɨ́ vílé áyʉ́ aluzàrɨ̀ nyáɨ́mà ágyíi òkùkù be kʉ Nível: Read aloud. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8777.png', NULL, 1080, 25, 20, 'asp-8777', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12194, 'Ídri  Nyǎzà Tí Òkpó Be Rɨ Nɨ Rɨ', 'lugbarati-(official)', 'Ó’dʉ́kó anzɨ nyɨ́rɨ́ yɨ̀nɨ́dɨ̀ tí mà drìá.  Ètúsɨ̀ mvá mvá avɨ́zʉ́ ndrɨ̀zà nɨ te ínísɨ̀ èrɨɨ́ oja ti òkpórʉ̌ tʉ̀ rɨ̀ rʉ́ à’dí ‘dɨzʉ́  e’yó ònzɨ́ be àgu mà ídri opazʉ́. Nível: First words. Ilustração: Danielle Bruckert.', 'http://africanstorybook.org/illustrations/covers/8778.png', NULL, 674, 25, 20, 'asp-8778', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12195, 'Drìléònzɨ́', 'lugbarati-(official)', 'Mváàzɨ́nɨnèmùtùkárɨ̀ gǎnɨ pi esúdrìléònzɨ́ mùtùkárɨ́ àmbónɨ be. Nível: First words. Ilustração: Cathy Feek.', 'http://africanstorybook.org/illustrations/covers/8779.png', NULL, 1147, 25, 20, 'asp-8779', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12196, 'Ágʉ̀pɨ́ Ɨ́zʉ̀ Rɨ́', 'lugbarati-(official)', 'Ágúpí ádɨ́kódɨ̀ mà alɨ́ádɨ̀ zò èzʉ́ lɨ́rɨ́ lɨ́rɨ́ fè ànɨ́ àfa drɨ́á èrɨ mà àgeɨ́ádɨ̀yɨ edá àlíá rʉ́ tʉ̀ kànɨ̀kʉ gǎkányaá rʉ́ tʉ̀. Ko eyó èwárʉ́ɨ́ vɨ́lé rɨ̀ mà àzà àfa drɨ́á edézà òcòɨ́ vɨ́lé rɨ̀sɨ̀ rɨ̀sɨ̀. Nível: First sentences. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/8780.png', NULL, 1473, 25, 20, 'asp-8780', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12197, 'Atako Vɨ́lé Àfa Gèrì E''daápɨ Rɨ̀', 'lugbarati-(official)', 'Zámvá gǎ engápɨ Wátɨ̀á ‘dɨ̀rɨ zòɨ́mà bírìsì àzɨ́ ndrɨ̀zà rʉ́ ndʉ́ ‘dɨ̀lénɨ be. Atako mà bírìsì ‘dɨ̀ nɨ èrɨ mà àzàko àfaònzɨ́ yɨ sɨ̀ nɨ̀. zámvá ndérɨ̀ kà àvɨ̀bé mà tálábo Nível: First sentences. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/8781.png', NULL, 471, 25, 20, 'asp-8781', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12198, 'Èwámvá Òlúkùlúá Be Rɨ̀', 'lugbarati-(official)', 'Ndráa drɨ̀ò rɨ̀sɨ̌ Nível: First sentences. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8782.png', NULL, 1080, 25, 20, 'asp-8782', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12199, 'Ndrí ''ɨ, Òcó ''ɨ Àzɨ́nɨ Tí ''ɨ', 'lugbarati-(official)', 'Ndríɨ Nível: First sentences. Ilustração: Marleen Visser.', 'http://africanstorybook.org/illustrations/covers/8783.png', NULL, 471, 25, 20, 'asp-8783', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12200, 'Òbólókó Àbírí Nɨ́ Ndě Rá Rɨ̀ Pɨ Cǔcǔ Be.', 'lugbarati-(official)', 'Òbólókó àzɨ́ àbírí nɨ́ ndě rá nɨ esú ámvúbánɨ́ patí éfɨ́ sazʉ́ cǔcǔ nizàrʉ́ nɨ nɨ́ɨ èyɨ̀zʉ́ kìlò rʉ́ àràkàlá nɨ mà síá nɨ. Òbólókó mbʉ patí éfɨ́ ètɨ̀zʉ́ te edé ngʉ́kʉ́ drìá. Òbɨ̀ mbúdà mà drìléádà mà drìléá te páalá drɨ́á èrɨ nɨ́ mbuzʉ́ rɨ̀ mà alɨ́á èrɨ edé ɨ́mà ngʉ́kʉ́ drɨ̀á àzó àzó. Èrɨ dɨ́ nga wé cǔcǔ ndê ètɨ̀ rá yǎ? Nível: First paragraphs. Ilustração: Benjamin Mitchley.', 'http://africanstorybook.org/illustrations/covers/8784.png', NULL, 1080, 25, 20, 'asp-8784', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12201, 'Álèàvásɨ̀', 'lugbarati-(official)', 'Ó’dʉ́kó ‘dɨ̀ àfa zámvá gàá nɨ nɨ́ lě àvásɨ̀ ‘dɨ̀yɨ mà drìá. Nível: First words. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8785.png', NULL, 471, 25, 20, 'asp-8785', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12202, 'Òbólókó Pɨ Ètú Be', 'lugbarati-(official)', 'Òbólókó òvʉ́ó rʉ́ rɨ̀bà ágyí ètú be. Lè èrɨ jí àkúá mú drìfúɨ́mà átíi be. Òbólókó ni ètú nɨɨ́mà ngúkʉ́á. Kó drì muzʉ́ àkúá te múnɨ́ rè kʉ yé. Nível: Longer paragraphs. Ilustração: Manyeka Arts Trust.', 'http://africanstorybook.org/illustrations/covers/8786.png', NULL, 1080, 25, 20, 'asp-8786', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12203, 'Má ''ɨ́ Àzɨ́nɨ Àkú Àma Vɨ́lé Rɨ̀', 'lugbarati-(official)', 'Á’dɨ́kó ‘dɨ̀rɨ e’yó nze eyó ágúpíámvá àzɨ́nɨ nɨ́ fʉ̀zʉ́ acízʉ́bá àkú àzɨ́ èrɨnɨ́ nìlé kʉnɨádɨ̀yɨ be nɨ mà drìá. Nível: First sentences. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8787.png', NULL, 1080, 25, 20, 'asp-8787', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12204, 'Àyákáká', 'lugbarati-(official)', 'Á’dɨ́kó ‘dɨ̀rɨ ágú àzɨ́ èrɨ mà òkʉ́nɨ nɨ́ ndráa èrɨ nɨ́ lʉ́ ezóanzɨ osizʉ́ɨ́ nɨ mà drìá. Ágú ndê erɨ̀ gbà òrì ɨ́mà òkʉ́ ‘dɨ̀ mà aléá kɨ́nɨ̀ vɨ́lé rɨ̀sɨ̀ kà zámvá osi díká ‘ɨ nga èrɨ ‘di rá Nível: First paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8788.png', NULL, 471, 25, 20, 'asp-8788', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12205, 'Ágúàzɨ́ Ndráaa’Ápɨa’Dúlerɨ̀', 'lugbarati-(official)', 'Á’dɨ́kó ‘dɨ̀rɨ ágú àzɨ́ ndráa lěpɨ a’ápɨ ‘bá àzɨ́ ‘dìyi pie kʉ nɨ mà drìá. Ágú ndê pɨ nzé yɨ mà jó síɨ́mà òkʉ́nɨ be ‘bá àzɨ́ ‘dìyi vʉ́ rɨ̀ sɨ̀ rè. Gbóróndʉ́á ‘dɨ̀rɨ ejí e’yó yi mà drìá àmbó. Nível: First sentences. Ilustração: Little Zebra Books and Trevor Kellog.', 'http://africanstorybook.org/illustrations/covers/8789.png', NULL, 471, 25, 20, 'asp-8789', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12206, 'Gǎtʉ̀', 'lugbarati-(official)', 'Cakʉrʉ́ mà bongo èyi wóró èrɨ nɨ́ gǎ tʉ̀. Èrɨ nga èyi ‘ye à’dʉrʉ́ yà? Nível: First words. Ilustração: Sandy Lightly.', 'http://africanstorybook.org/illustrations/covers/8790.png', NULL, 471, 25, 20, 'asp-8790', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12207, 'Ròbí Yɨ Mà ''bɨ́ko Yo À''dɨ E''yósɨ̀à Rɨ̀', 'lugbarati-(official)', 'Ádɨ́kó Áfíríkàádɨ̀ádɨ̀yɨ mà aléá drɨ́á Ètóó mà rú ècè nɨ́ kʉ.Bá nì Ètóó nɨ adrɨ́zàònzɨ́ èrɨ nɨ́yelé pángá esú kókòrʉ́dɨ̀yɨ sɨ̀. Ádɨ́kódɨ̀ mà aléá àmà nga àdɨyeɨ́ sâ Ètóó nɨ́ gàzʉ́ Ròbí nɨ trʉ̀kósɨ̀ Ròbí nɨ́ pá tìzʉ́ èrɨ mà pá drɨábo rɨ̀ sɨ̀ rɨ̀ mà vútiá nɨ̀ yà rɨ̀ nè. Nível: First sentences. Ilustração: Little Zebra Books and Carol Liddiment.', 'http://africanstorybook.org/illustrations/covers/8791.png', NULL, 471, 25, 20, 'asp-8791', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12208, 'A’Ú Pi Yúkú Be', 'lugbarati-(official)', 'Ándrá drɨ̀ò a’ú pi yúkú be ágyíirú. À’ú aí sìndánì yúkú vʉ́. Sìndánì  àvì rá. Àwókó nya Yúkú nɨ tʉ̀ Nível: First paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8792.png', NULL, 1080, 25, 20, 'asp-8792', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12209, 'Onyúkunyú Pi Drìkùlù Be', 'lugbarati-(official)', 'Onyúkunyú pi ndráa Drìkùlù be ágyí nɨ. O’dú àlʉ èyi gá àgátà à’dɨ ecó yí àra mà dri zó rá nɨ̀ yà rì mà drìá. Drìkùlù ‘de yí ètɨ́á. Onyúkunyú gu ‘ɨ káɨ̀ rá tini àsɨ̀ ‘ɨ wàlà wàlà. Nível: First sentences. Ilustração: Joshua Waswa.', 'http://africanstorybook.org/illustrations/covers/8793.png', NULL, 1473, 25, 20, 'asp-8793', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12210, 'Èbǐo Pǐ, Gǎagǎa Pɨe Àzɨnɨ Éyío Pɨe', 'lugbarati-(official)', 'Èbǐo ànyàmbòlò rʉ́ rɨ òbɨ̀ ɨ́ mà àgyí gǎagǎa pi olé ɨ́ drí  elío éfí fèzʉ́ tʉ ágá èrɨnɨ́ té ecólé nyalérɨ rá. Gǎgǎ ísú èrí mà lókírí rá Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8794.png', NULL, 1080, 25, 20, 'asp-8794', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12211, 'Ebìó Òvʉ́ó Rʉ Rɨ̀', 'lugbarati-(official)', 'Èbìó ànɨ̀káníkà rʉ́ rɨ̀ lè àfa nyazà tʉ̀ te lènɨ́ àzí nyaká adɨ́zʉ́ rɨ̀ ngá kʉ. Esú lókìrí àzɨ́nɨ fèzʉ’ èrɨ mà agyípɨ́ yɨnɨ́ ecózʉ́ èrɨ omvezʉ́ sâ nyaká nɨ́ ofʉzʉ́bo rɨ̀ sɨ̀ nɨ. Te drìléònzɨ́ rʉ́ lókìrídà nga drìléònzɨ́ fě bè èrɨnɨ́ ànɨ’dà banɨ eyó fěpɨ ànɨ̀kánɨ́kà yɨ mà pá yɨnɨ́ ovʉzʉ èzʉ́ èzʉ́ àzɨ́nɨ èzɨ́á èzɨ́á rɨ̀ɨ́. Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8795.png', NULL, 1473, 25, 20, 'asp-8795', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12212, 'Ma Adrigaaovuoruri', 'lugbarati-(official)', 'Mvá àzɨ́ ángɨ́rɨ́á nɨ ecá àwókó sɨ̀ ɨ́mà ádrɨ́i wereá rɨ̀ be èrɨ nɨ́ɨ́mà sâ ayʉ́zʉ́ drɨ́á drɨ́á avɨ́zʉ́ dè esú èrɨɨ̂nɨ́ àzí drɨ́á jóádɨ̀yɨ nga rɨ̀ sɨ̀. Nível: First words. Ilustração: Mlungisi Dlamini.', 'http://africanstorybook.org/illustrations/covers/8796.png', NULL, 4341, 25, 20, 'asp-8796', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12213, 'Wárágà', 'lugbarati-(official)', 'Ódʉ́kódɨ̀ zámvá àzɨ́ wereá àzórʉ̌ ànɨ́ acípɨ sùkúlùá kʉ nɨ mà drìá. Wárágà yɨ gèrì àlʉ zámvádɨ̀ nɨ́ ódúkó ìdrìzʉ́ sâ èrɨ nɨ́ ovʉzʉ́ àzôrʉ́ rɨ̀sɨ̀dìyɨ. Nível: First words. Ilustração: Cathy Feek.', 'http://africanstorybook.org/illustrations/covers/8797.png', NULL, 471, 25, 20, 'asp-8797', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12214, 'Mɨ́ Erɨ E''yó Mâ Ruá Mà Tiá', 'lugbarati-(official)', 'Àma àlʉ àlʉ ovʉ ruá be ndrɨ̀zàrʉ́. Mɨ́ erɨ òku drɨ̀ò eyó mɨ̂ ruá mà tiábo? Nível: First words. Ilustração: Angie & Upesh.', 'http://africanstorybook.org/illustrations/covers/8798.png', NULL, 1080, 25, 20, 'asp-8798', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12215, 'Candiru Pi Dri''biifi Na ‘Diyi Be', 'lugbarati-(official)', 'Ezóanzɨ na mú éjá òwʉ̌ ètú drɨ́pɨ tʉ̀ nɨ mà alɨ́á sɨ̀. kó drì mú yɨ́ wě. Sâ yɨ nɨ́ yɨ wèzʉ́ dèzʉ́bo rɨ̀sɨ̌ Nível: Longer paragraphs. Ilustração: Wiehan de Jager.', 'http://africanstorybook.org/illustrations/covers/8799.png', NULL, 4341, 25, 20, 'asp-8799', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12216, 'Anzɨ Ìrì Àbírí Nɨ́ Fulé Káyɨ̀ ''dɨ̀yɨ', 'lugbarati-(official)', 'Ádɨ́kódɨ̀ nze eyó  anzɨ ìrì àbírí nɨ́ fulé káì rá òtɨ̀lɨ̀pátɨ̀á yɨ mà dèdé nɨ́ adɨ́ mudrídɨ`yɨ awaápɨ yɨ mà èseléádɨ̀yɨ mà drìá. Nível: First words. Ilustração: Bronwen Heath.', 'http://africanstorybook.org/illustrations/covers/8800.png', NULL, 1473, 25, 20, 'asp-8800', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12217, 'A Dancer''s Tale: The Story of Phyllis Spira', 'en', 'This is the story of the life of Phyliis Spira Nível: First paragraphs. Ilustração: Thea Nicole de Klerk.', 'http://africanstorybook.org/illustrations/covers/8815.png', NULL, 3738, 25, 20, 'asp-8815', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12218, 'A Fish and a Gift', 'en', 'Yusuf waits in anticipation for his father to return from fishing.  He has promised to bring Yusuf a gift today. Nível: Longer paragraphs. Ilustração: Jesse Breytenbach.', 'http://africanstorybook.org/illustrations/covers/8831.png', NULL, 705, 25, 20, 'asp-8831', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12219, 'Graca''s Dream', 'en', 'The inspiring story of Graca Machel Nível: Read aloud. Ilustração: Karlien de Villiers and Marike le Roux.', 'http://africanstorybook.org/illustrations/covers/8869.png', NULL, 4343, 25, 20, 'asp-8869', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (12220, 'Paka Mwerevu', 'sw', 'Bwana Kio ana paka mwerevu anayeitwa Safi. Nível: First sentences. Ilustração: Catherine Groenewald.', 'http://africanstorybook.org/illustrations/covers/8877.png', NULL, 204, 25, 20, 'asp-8877', 'cc-by', 0, NULL);
